class TestBuildToolConfigs:

    def test_priority_targets_first(self):
        probe = _make_probe()
        probe.agent_analysis = {
            "tool_analyses": {
                "tool_a": {"attack_prompts": ["a"]},
                "tool_b": {"attack_prompts": ["b"]},
                "tool_c": {"attack_prompts": ["c"]},
            },
            "priority_targets": [
                "tool_c - most dangerous",
                "tool_a - also dangerous",
            ],
        }
        configs = probe._build_tool_configs()
        names = [name for name, _ in configs]
        assert names == ["tool_c", "tool_a", "tool_b"]

    def test_no_duplicates(self):
        probe = _make_probe()
        probe.agent_analysis = {
            "tool_analyses": {
                "tool_a": {"attack_prompts": ["a"]},
            },
            "priority_targets": [
                "tool_a - important",
            ],
        }
        configs = probe._build_tool_configs()
        names = [name for name, _ in configs]
        assert names == ["tool_a"]

    def test_case_insensitive_match(self):
        probe = _make_probe()
        probe.agent_analysis = {
            "tool_analyses": {
                "File_Reader": {"attack_prompts": ["a"]},
            },
            "priority_targets": [
                "file_reader - vuln",
            ],
        }
        configs = probe._build_tool_configs()
        names = [name for name, _ in configs]
        assert names == ["File_Reader"]

    def test_remaining_tools_appended(self):
        probe = _make_probe()
        probe.agent_analysis = {
            "tool_analyses": {
                "tool_a": {"attack_prompts": ["a"]},
                "tool_b": {"attack_prompts": ["b"]},
            },
            "priority_targets": [],
        }
        configs = probe._build_tool_configs()
        names = [name for name, _ in configs]
        assert set(names) == {"tool_a", "tool_b"}
        assert len(names) == 2

    def test_malformed_tool_analyses_list_ignored(self):
        probe = _make_probe()
        probe.agent_analysis = {
            "tool_analyses": [{"name": "x"}],
            "priority_targets": [],
        }
        assert probe._build_tool_configs() == []

    def test_non_string_priority_targets_skipped(self):
        probe = _make_probe()
        probe.agent_analysis = {
            "tool_analyses": {"tool_a": {"attack_prompts": ["a"]}},
            "priority_targets": [None, "tool_a - vuln"],
        }
        configs = probe._build_tool_configs()
        assert [name for name, _ in configs] == ["tool_a"]

    def test_malformed_tools_config_ignored(self):
        probe = _make_probe()
        probe.agent_config = {"tools": ["rm -rf /"]}
        assert probe._format_tools_for_analysis() == ""

    def test_non_dict_tool_entry_skipped(self):
        probe = _make_probe()
        probe.agent_config = {
            "tools": ["bad", {"name": "good", "description": "d"}],
        }
        out = probe._format_tools_for_analysis()
        assert "### Tool: good" in out
        assert "### Tool: bad" not in out


